const stageCopyKey: Record<DealStage, CopyKey> = { mapped: 'mapped', analyse: 'analyse', first_call: 'firstCall', diligence: 'diligence', ic: 'ic', invested: 'invested', no_go: 'noGo' };
const roleCopyKey: Record<RoleId, CopyKey> = { admin: 'roleAdmin', reviewer: 'roleReviewer', editor: 'roleEditor', viewer: 'roleViewer', founder: 'roleFounder' };
const reviewCopyKey = (status: string): CopyKey => status === 'not_applicable' ? 'notApplicable' : status === 'verified' ? 'verified' : status === 'rejected' ? 'rejected' : status === 'conflict' ? 'conflict' : 'awaitingReview';

