  const [loginError, setLoginError] = useState(false);

  const [companies, setCompanies] = useState<Company[]>(() => { const saved = loadStored<Company[]>('companies-v2', initialCompanies); return saved.length >= initialCompanies.length ? saved : initialCompanies; });
